	// EXPECT-2: cache_warmup_e2e_ms < 4280
	// HYPOTHESIS-3: Strong session affinity (0.87) with quadratic overload safety valve preserves multiturn cache hits
	// MECHANISM-3: Long-prefix sessions benefit greatly from cache reuse; quadratic penalty at avg+2 prevents the affinity instance from becoming a bottleneck
	// EXPECT-3: multiturn_e2e_ms < 165
	inputLen := len(req.InputTokens)
	w0 := ws.weights[0]
	w1 := ws.weights[1]
	if len(ws.weights) >= 2 {
		if inputLen < 96 {
			w0, w1 = 0.03, 0.97
		} else if inputLen < 256 {
			w0, w1 = 0.25, 0.75
		} else {
			w0, w1 = 0.55, 0.45
		}
		if req.SLOClass == "realtime" {
			w0 *= 0.4
			w1 *= 1.5
		} else if req.SLOClass == "batch" {
			w0 *= 1.2
			w1 *= 0.85
		}
		if req.SessionID != "" && inputLen >= 128 {
			w0, w1 = 0.87, 0.13
		}
		t := w0 + w1
		if t > 0 { w0 /= t; w1 /= t }
	}
	prefixScores := ws.scorers[0](req, snapshots)
	maxPrefix := 0.0
	for _, snap := range snapshots {
		if prefixScores[snap.ID] > maxPrefix { maxPrefix = prefixScores[snap.ID] }
	}
	if maxPrefix < 0.05 {
		w0, w1 = 0.0, 1.0
	}
	scores := make(map[string]float64, len(snapshots))
	for _, snap := range snapshots {
		s := prefixScores[snap.ID]
		if s < 0 { s = 0 }
		if s > 1 { s = 1 }
		scores[snap.ID] += s * w0
	}
	for i := 1; i < len(ws.scorers); i++ {
		dimScores := ws.scorers[i](req, snapshots)
		w := w1
		if i >= 2 { w = ws.weights[i] }
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 { s = 0 }
			if s > 1 { s = 1 }
			scores[snap.ID] += s * w
		}
	}
	minLoad, totalLoad := snapshots[0].EffectiveLoad(), 0
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		if el < minLoad { minLoad = el }
		totalLoad += el
	}
	avgLoad := float64(totalLoad) / float64(len(snapshots))
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		diff := float64(el - minLoad)
		if diff > 0 {
			p := 0.06 * diff
			if req.SLOClass == "realtime" { p = 0.09 * diff }
			scores[snap.ID] -= p
		}
