		ps := prefixScores[snap.ID]
		cacheBonus := 0.0
		if ps > 0.5 { cacheBonus = ps * 1.2 }
		thresh := avgLoad + 2.0 + cacheBonus
		if thresh < 4.0 { thresh = 4.0 }
		if float64(el) > thresh {
			ex := float64(el) - thresh
			scores[snap.ID] -= 0.10 * ex * ex
		}
		// Wider idle bonus window helps spread load during high-rate warmup
		if el <= minLoad+1 && minLoad < 5 {
			scores[snap.ID] += 0.04
		}
	}
	bestScore := -1e9
	bestIdx := 0
	for i, snap := range snapshots {
		s := scores[snap.ID]
		// CacheHitRate bonus for session requests (helps multiturn convergence)
		if req.SessionID != "" && snap.CacheHitRate > 0.01 {
			s += snap.CacheHitRate * 0.03
		}
		// KV utilization penalty for very full instances (avoids memory pressure stalls)
		if snap.KVUtilization > 0.85 {
			s -= (snap.KVUtilization - 0.85) * 0.3
		}
		if s > bestScore {
			bestScore = s
			bestIdx = i
		}
	}
	// EVOLVE-BLOCK-END

	// Notify observers of routing decision (stateful scorers update their state)
	for _, obs := range ws.observers {
		obs(req, snapshots[bestIdx].ID)
	}

	return NewRoutingDecisionWithScores(
		snapshots[bestIdx].ID,
		fmt.Sprintf("weighted-scoring (score=%.3f)", bestScore),
		scores,
	)
